const MindliMusic=(()=>{let ctx=null,master=null,bgTimer=null,bgStep=0,introDone=false;
 function ensure(){if(!ctx){const C=window.AudioContext||window.webkitAudioContext;if(!C)return null;ctx=new C();master=ctx.createGain();master.gain.value=.055;master.connect(ctx.destination)}if(ctx.state==='suspended')ctx.resume().catch(()=>{});return ctx}
 function note(freq,when,dur,gain=.22,type='sine'){if(!ensure())return;const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,when);g.gain.setValueAtTime(.0001,when);g.gain.exponentialRampToValueAtTime(gain,when+.035);g.gain.exponentialRampToValueAtTime(.0001,when+dur);o.connect(g).connect(master);o.start(when);o.stop(when+dur+.03)}
 function intro(){if(introDone||Core.settings.introMusic===false)return;introDone=true;if(!ensure())return;const n=[392,523.25,659.25,783.99];n.forEach((f,i)=>note(f,ctx.currentTime+i*.16,.42,i===3?.17:.12,'sine'))}
 function startBg(){if(Core.settings.backgroundMusic===false||bgTimer)return;if(!ensure())return;const seq=[261.63,329.63,392,329.63,293.66,349.23,440,349.23];const tick=()=>{if(Core.settings.backgroundMusic===false){stopBg();return}note(seq[bgStep++%seq.length],ctx.currentTime,.75,.045,'sine')};tick();bgTimer=setInterval(tick,1050)}
 function stopBg(){if(bgTimer){clearInterval(bgTimer);bgTimer=null}}
 function sync(){if(Core.settings.backgroundMusic===false)stopBg()}
 document.addEventListener('pointerdown',()=>intro(),{once:true,passive:true});document.addEventListener('keydown',()=>intro(),{once:true});
 return{intro,startBg,stopBg,sync};})();

