function bottomNavigation(active='play'){return `<nav class="bottom-nav" aria-label="Hlavná navigácia"><button data-main-tab="play" class="${active==='play'?'active':''}"><span>⌂</span><small>Hrať</small></button><button data-main-tab="learn" class="${active==='learn'?'active':''}"><span>◎</span><small>Učiť sa</small></button><button data-main-tab="together" class="${active==='together'?'active':''}"><span>♟</span><small>Spolu</small></button><button data-main-tab="profile" class="${active==='profile'?'active':''}"><span>●</span><small>Profil</small></button></nav>`;}
