function showRewardShop(){const p=Core.profile();p.boosters??={};const mission=dailyMission();app.innerHTML=`<section class="screen feature-screen wallet-screen">${screenHeader('Peňaženka a obchod','Koruny na hru · mince za aktivitu')}<div class="wallet-overview panel"><div><small>Herné koruny</small><strong>${money(p.endlessWallet)}</strong><span>stávky a rýchle nákupy</span></div><i></i><div><small>Mince</small><strong>${new Intl.NumberFormat().format(p.coins||0)}</strong><span>trvalé odmeny</span></div></div><section class="coin-guide panel"><div><strong>Ako získaš mince</strong><small>Dnes: ${mission.answered||0}/5 otázok · ${mission.correct||0}/3 správne</small></div><div class="coin-rule-grid"><span><b>+10</b> dokončený kvíz</span><span><b>+10</b> prvá hra dňa</span><span><b>+20</b> kvíz bez chyby</span><span><b>+30</b> denná misia</span><span><b>+30</b> denná výzva</span><span><b>+50</b> nová úroveň</span></div></section><h2 class="wallet-shop-title">Pomôcky do kvízu</h2><div class="reward-shop compact-shop">${Object.entries(BOOSTER_SHOP).map(([id,x])=>`<article class="panel reward-item compact"><span>${x.icon}</span><div><strong>${x.name}</strong><small>Vlastníš ${boosterCount(id)}</small></div><div class="reward-buy-actions"><button data-buy-booster="${id}" ${(p.coins||0)<x.cost?'disabled':''}>${x.cost} mincí</button><button data-buy-booster-kr="${id}" ${p.endlessWallet<Math.ceil(x.cost*2.5)?'disabled':''}>${Math.ceil(x.cost*2.5)} kr</button></div></article>`).join('')}</div><div class="wallet-footnote">Mince nestrácaš pri zlej odpovedi. Koruny sú herné konto a pri stávkach môžu rásť aj klesať.</div></section>`;resetScroll();bindNavigation();document.querySelectorAll('[data-buy-booster]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.buyBooster,x=BOOSTER_SHOP[id];if(!x||(p.coins||0)<x.cost)return;p.coins-=x.cost;p.boosters[id]=boosterCount(id)+1;Core.persistProfiles();toast(`${x.name}: kupón bol pridaný.`,'good');showRewardShop();}));document.querySelectorAll('[data-buy-booster-kr]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.buyBoosterKr,x=BOOSTER_SHOP[id],cost=Math.ceil(x.cost*2.5);if(buyWithWallet(cost,`Kupón ${x.name}`,pp=>{pp.boosters??={};pp.boosters[id]=boosterCount(id)+1;}))showRewardShop();}));}

