function allActiveQuestions(){return allPlayableQuestions();}
function clearSavedGame(){const p=Core.profile();if(p.savedGame){p.savedGame=null;Core.persistProfiles();}}
function saveGameState(phase='bet',resumePosition=position){
  if(duel||currentSpecial==='online'||!currentCategory||!round.length)return;
  if(unlimitedRound&&resumePosition>=round.length)extendUnlimitedRound();
  if(!unlimitedRound&&resumePosition>=round.length){clearSavedGame();return;}
  const p=Core.profile();p.savedGame={version:1,savedAt:Date.now(),categoryId:currentCategory.id,currentSpecial,gameMode,answerMode,selectedDifficulty,selectedCount,
    roundIds:round.map(question=>question.id),roundSourceIds:roundSource.map(question=>question.id),position:resumePosition,score,wallet,wager,nextWager,wagerLocked,totalWagered,
    roundCorrectStreak,roundBestStreak,roundWrong,skipped,lifelinesUsed:{...lifelinesUsed},roundStartWallet,unlimitedRound,phase};Core.persistProfiles();
}
function savedGameLabel(saved){const category=Core.bank.categories.find(item=>item.id===saved.categoryId);return `${category?.name||'Rozohraná hra'} · otázka ${Number(saved.position)+1}${saved.unlimitedRound?' · bez limitu':''}`;}
function restoreSavedGame(){
  const p=Core.profile(),saved=p.savedGame;if(!saved)return;
  const map=new Map(allActiveQuestions().map(question=>[question.id,question])),savedRound=(saved.roundIds||[]).map(id=>map.get(id)).filter(Boolean).map(trainingQuestion),savedSource=(saved.roundSourceIds||[]).map(id=>map.get(id)).filter(Boolean).map(trainingQuestion);
  if(!savedRound.length||savedRound.length!==(saved.roundIds||[]).length||saved.position<0||saved.position>=savedRound.length){clearSavedGame();toast('Uloženú hru už nebolo možné obnoviť.','bad');return showHome();}
  clearGameTimer();currentSpecial=saved.currentSpecial||null;duel=null;onlineSession=null;gameMode=saved.gameMode||'classic';answerMode=saved.answerMode||'choice';selectedDifficulty=saved.selectedDifficulty||'progressive';selectedCount=saved.selectedCount??10;
  round=savedRound;roundSource=savedSource.length?savedSource:savedRound;position=Number(saved.position)||0;score=Number(saved.score)||0;wallet=Number(saved.wallet);wager=Number(saved.wager)||100;nextWager=Number(saved.nextWager)||wager;wagerLocked=!!saved.wagerLocked;totalWagered=Number(saved.totalWagered)||0;
  roundCorrectStreak=Number(saved.roundCorrectStreak)||0;roundBestStreak=Number(saved.roundBestStreak)||0;roundWrong=Number(saved.roundWrong)||0;skipped=Number(saved.skipped)||0;lifelinesUsed=saved.lifelinesUsed||{};roundStartWallet=Number(saved.roundStartWallet)||START_WALLET;unlimitedRound=!!saved.unlimitedRound;roundHistorySaved=false;
  const source=Core.bank.categories.find(category=>category.id===saved.categoryId);currentCategory=source||{id:saved.categoryId,name:saved.categoryId==='favorites'?'Obľúbené otázky':saved.categoryId==='mix'?'Náhodný mix':'Rozohraná hra',icon:saved.categoryId==='favorites'?'★':'MX'};document.body.dataset.category=currentCategory.id;
  localStorage.setItem('quiz-game-mode',gameMode);localStorage.setItem('quiz-mode-v2',answerMode);localStorage.setItem('quiz-difficulty-v3',selectedDifficulty);localStorage.setItem('quiz-count-v2',selectedCount);
  resetQuestionTools();toast('Rozohraná hra bola obnovená.','good');saved.phase==='question'?showQuestion():preQuestion();
}
function isFavorite(questionId){return Core.profile().favorites.includes(questionId);}
function toggleFavorite(questionId){const p=Core.profile();p.favorites=isFavorite(questionId)?p.favorites.filter(id=>id!==questionId):[...p.favorites,questionId].slice(-500);Core.persistProfiles();toast(isFavorite(questionId)?'Otázka bola pridaná medzi obľúbené.':'Otázka bola odstránená z obľúbených.','good');}
function applyPreset(config){selectedCount=config.count;selectedDifficulty=config.difficulty;answerMode=config.answerMode;gameMode=config.gameMode;localStorage.setItem('quiz-count-v2',selectedCount);localStorage.setItem('quiz-difficulty-v3',selectedDifficulty);localStorage.setItem('quiz-mode-v2',answerMode);localStorage.setItem('quiz-game-mode',gameMode);showHome();}
function startCategoryRound(categoryId){if(!adminUnlocked()&&!EDITORIALLY_RELEASED_CATEGORIES.has(categoryId))return toast('Tento okruh ešte prechádza redakčnou kontrolou.','bad');
  const category=Core.bank.categories.find(item=>item.id===categoryId);if(!category)return toast(ui('Vybraný okruh nie je dostupný.'),'bad');
  if(gameMode==='mix'){gameMode='classic';localStorage.setItem('quiz-game-mode',gameMode);toast(ui('Spúšťam zvolený okruh. Náhodný mix bol vypnutý.'),'good');}
  if(/^\d$/.test(String(selectedDifficulty))&&!category.questions.some(question=>question.difficulty===Number(selectedDifficulty))){selectedDifficulty='progressive';localStorage.setItem('quiz-difficulty-v3',selectedDifficulty);toast('Vo vybranom okruhu zatiaľ nie sú redakčne schválené otázky tejto úrovne. Spúšťam postupnú náročnosť.','good');}
  const prefs=profilePreferences();prefs.lastCategoryId=categoryId;Core.persistProfiles();startRound(categoryId);
}


