let miniPerkMessageHandler=null;
let miniRewardMessageHandler=null;
function attachMiniRewardBridge(id,frame){if(miniRewardMessageHandler)window.removeEventListener('message',miniRewardMessageHandler);miniRewardMessageHandler=e=>{if(e.source!==frame.contentWindow||e.data?.type!=='mindli-mini-reward'||e.data.app!==id)return;const p=Core.profile(),amount=Math.max(1,Math.min(20,Math.round(Number(e.data.coins)||0))),key=String(e.data.key||''),today=Core.today();p.miniRewardKeys??={};p.miniDailyRewards??={};const permanent=Boolean(e.data.permanent);const token=`${id}:${key}`;if(permanent&&key&&p.miniRewardKeys[token])return;const daily=Number(p.miniDailyRewards[today]||0);if(!permanent&&daily>=25)return;if(permanent&&key)p.miniRewardKeys[token]=true;const grant=permanent?amount:Math.min(amount,25-daily);if(grant<=0)return;p.miniDailyRewards[today]=daily+grant;addCoins(grant,`${miniAppText(id)?.title||id} · odmena`);const old=Object.keys(p.miniDailyRewards).sort().slice(0,-14);old.forEach(k=>delete p.miniDailyRewards[k]);Core.persistProfiles();toast(`+${grant} mincí · ${miniAppText(id)?.title||'Minihra'}`,'good');};window.addEventListener('message',miniRewardMessageHandler);}

function attachMiniPerkBridge(id,frame){if(miniPerkMessageHandler)window.removeEventListener('message',miniPerkMessageHandler);miniPerkMessageHandler=e=>{if(e.source!==frame.contentWindow||e.data?.type!=='mindli-mini-consume'||e.data.app!==id)return;const perk=e.data.perk,p=Core.profile(),n=miniPerkCount(id,perk);if(n>0){p.miniPerks[id][perk]=n-1;Core.persistProfiles();try{frame.contentWindow.postMessage({type:'mindli-mini-state',app:id,perks:p.miniPerks[id]},'*')}catch{}}};window.addEventListener('message',miniPerkMessageHandler);}

function teardownMiniAppBridge(){
  if(miniAppNativeRestore){try{miniAppNativeRestore();}catch{}miniAppNativeRestore=null;}if(miniPerkMessageHandler){window.removeEventListener('message',miniPerkMessageHandler);miniPerkMessageHandler=null;}if(miniRewardMessageHandler){window.removeEventListener('message',miniRewardMessageHandler);miniRewardMessageHandler=null;}
}
function attachMiniAppBridge(id,frame){
  teardownMiniAppBridge();
  if(id!=='piskvorky'||!window.MultiplayerNative||typeof window.MultiplayerNative.onNativeEvent!=='function')return;
  const hostNative=window.MultiplayerNative,original=hostNative.onNativeEvent;
  const proxy=function(raw){
    try{
      const target=frame?.contentWindow?.MultiplayerNative;
      if(target&&typeof target.onNativeEvent==='function'){target.onNativeEvent(raw);return;}
    }catch{}
    original.call(hostNative,raw);
  };
  hostNative.onNativeEvent=proxy;
  miniAppNativeRestore=()=>{if(hostNative.onNativeEvent===proxy)hostNative.onNativeEvent=original;};
}
function showMiniApp(id){
  const item=miniAppText(id);if(!item)return showHome();
  miniAppHomeScrollY=window.scrollY||document.documentElement.scrollTop||0;
  teardownMiniAppBridge();
  clearGameTimer();clearComputerTimer();if(onlineSession)stopOnlineConnection();
  const mt=MINI_APP_I18N[appLanguage()]||{back:'Späť do Mindli',reload:'Znovu načítať',host:'Mindli · miniaplikácia'};
  app.innerHTML=`<section class="screen miniapp-screen"><header class="miniapp-hostbar"><button id="miniAppBack" aria-label="${escapeHtml(mt.back)}">‹</button><div><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(mt.host)}</small></div><span class="mini-wallet-chip">${money(Core.profile().endlessWallet)}</span>${Object.keys(MINI_PERK_SHOP[id]||{}).length?'<button id="miniAppShop" class="mini-shop-button" aria-label="Obchod">🛒</button>':''}<button id="miniAppReload" aria-label="${escapeHtml(mt.reload)}">↻</button></header><iframe id="miniAppFrame" class="miniapp-frame" src="${item.src}?lang=${encodeURIComponent(appLanguage())}&host=mindli" title="${escapeHtml(item.title)}" allow="clipboard-read; clipboard-write" referrerpolicy="no-referrer"></iframe></section>`;
  resetScroll();
  const frame=document.getElementById('miniAppFrame');
  frame.addEventListener('load',()=>{attachMiniAppBridge(id,frame);attachMiniPerkBridge(id,frame);attachMiniRewardBridge(id,frame);try{frame.contentWindow.postMessage({type:'mindli-mini-state',app:id,perks:Core.profile().miniPerks?.[id]||{},language:appLanguage(),theme:document.documentElement.dataset.theme||'light',palette:document.documentElement.dataset.palette||'',themeChoice:Core.settings.theme||'system',largeText:!!Core.settings.largeText,largeButtons:!!Core.settings.largeButtons,colorblind:!!Core.settings.colorblind,animations:!!Core.settings.animations,sound:!!Core.settings.sound,introMusic:Core.settings.introMusic!==false,backgroundMusic:Core.settings.backgroundMusic!==false,vibration:!!Core.settings.vibration},'*')}catch{}});
  document.getElementById('miniAppShop')?.addEventListener('click',()=>showMiniShopDialog(id));
  document.getElementById('miniAppBack').addEventListener('click',()=>{const y=miniAppHomeScrollY;teardownMiniAppBridge();showHome();requestAnimationFrame(()=>requestAnimationFrame(()=>window.scrollTo({top:y,behavior:'auto'})));});
  document.getElementById('miniAppReload').addEventListener('click',()=>{teardownMiniAppBridge();frame.src=frame.src;});
}

