  try{const checkpoint=JSON.parse(localStorage.getItem('quiz-online-host-checkpoint-v42')||'null');if(checkpoint&&Date.now()-checkpoint.savedAt<7200000){const button=document.createElement('button');button.className='primary match-history-button';button.id='restoreOnlineGame';button.textContent='Obnoviť prerušenú Wi‑Fi hru';document.querySelector('.multiplayer-mode-grid').after(button);button.addEventListener('click',restoreOnlineHostCheckpoint);}}catch(_){}
