    app.innerHTML=`<section class="screen feature-screen">${screenHeader('Viac telefónov','Dostupné v nainštalovanej Android aplikácii')}<div class="panel empty-state"><h2>Sieťová hra potrebuje Android aplikáciu</h2><p>V prehliadačovej ukážke nie je prístup k lokálnej sieti. Nainštaluj APK na všetky telefóny.</p><button class="primary" id="onlineBack">Späť</button></div></section>`;resetScroll();bindNavigation();document.getElementById('onlineBack').addEventListener('click',showMultiplayerHub);return;
